  @RequestName VARCHAR(255),
  @RequestType VARCHAR(255)
) AS
BEGIN
  IF NOT EXISTS (SELECT * FROM DodLookup WHERE RequestID = @RequestID AND RequestName = @RequestName AND RequestType = @RequestType) THEN
